local M=require('desktop_model');local V=require('vessels');local T=require('desktop_samples');local G=require('genome');local S=require('persistence');local Worlds=require('desktop_worlds');local Store=require('desktop_store');local E=require('genome_editor')
local Tests={}
function Tests.run(B,native)
 local lines,failed={},0
 local function test(name,fn) local ok,why=xpcall(fn,debug.traceback);lines[#lines+1]=(ok and 'PASS ' or 'FAIL ')..name;if not ok then failed=failed+1;lines[#lines+1]=why end end
 local monitors={{id='primary',x=0,y=0,w=1920,h=1040,dpi=96,primary=true},{id='left',x=-2560,y=-200,w=2560,h=1400,dpi=144},{id='above',x=0,y=-1200,w=1600,h=1200,dpi=120}}
 local function state() local s=B.new(20261111);B.collect(s);V.ensure(s);M.ensure(s);Worlds.ensure(s);return s end
 local function seeded() local s=state();assert(T.seed(s,s.vessels[5].id,1));return s end
 test('Desktop object identities and common properties',function() local s=state();local a=M.add(s,'dish',s.vessels[1].id);local b=M.add(s,'dish',s.vessels[2].id);assert(a.id~=b.id and a.scale==1 and a.locked==false and a.entityId==s.vessels[1].id) end)
 test('Petri drag across negative-coordinate and mixed-DPI monitors',function() local s=state();local o=M.add(s,'dish',1,nil,100,100);assert(M.beginDrag(o,{x=120,y=125}));M.drag(o,{x=-2200,y=-100});assert(o.x==-2220 and o.y==-125);M.endDrag(o,monitors);assert(o.monitor=='left' and o.preferred.monitor=='left');local w=M.dimensions(o,monitors[2]);assert(w==354);local x,y=M.localPoint(o,monitors[2],o.x+150,o.y+150);assert(x==100 and y==100) end)
 test('Locked object rejects dragging',function() local o={locked=true,x=1,y=2};assert(not M.beginDrag(o,{x=0,y=0}));assert(not M.drag(o,{x=8,y=8}) and o.x==1) end)
 test('Monitor disconnection uses visible fallback without losing preferred position',function() local s=state();local o=M.add(s,'dish',1,nil,-2100,-100);M.remember(o,monitors);local preferred=S.encode(o.preferred);M.restore(o,{monitors[1]});assert(o.x>=0 and S.encode(o.preferred)==preferred);M.restore(o,monitors);assert(o.x==-2100 and o.y==-100) end)
 test('Resolution and DPI changes preserve logical offsets and clamp on-screen',function() local s=state();local o=M.add(s,'dish',1,nil,1500,800);M.remember(o,monitors);M.restore(o,{{id='primary',x=0,y=0,w=1280,h=720,dpi=144}});local w,h=M.dimensions(o,{dpi=144});assert(o.x+w<=1280 and o.y+h<=720) end)
 test('Layout restoration preserves dimensions, locks and identities',function() local s=state();local o=M.add(s,'dish',7,nil,100,200);o.locked=true;o.scale=1.2;M.remember(o,monitors);local saved=M.layout(s);o.x=99;o.scale=.5;o.locked=false;M.applyLayout(s,saved,monitors);assert(o.x==100 and o.y==200 and o.locked and o.scale==1.2 and #s.desktop.objects==1) end)
 test('Hiding laboratory preserves equipment, samples and independent habitat visibility',function() local s=seeded();local dish=M.add(s,'dish',s.vessels[1].id);local habitat=M.add(s,'terrarium','terrarium','habitats');dish.locked=true;local before=S.encode(s.vessels);local layout=S.encode(dish);M.setGroup(s,'laboratory',false);assert(not M.isVisible(s.desktop,dish) and M.isVisible(s.desktop,habitat));M.setGroup(s,'laboratory',true);assert(M.isVisible(s.desktop,dish) and S.encode(s.vessels)==before and S.encode(dish)==layout and #s.desktop.objects==2) end)
 test('Dropper withdraws counted sample, then adds it to the same persistent destination',function() local s=seeded();local src,dst=s.vessels[5],s.vessels[1];local sourceId,destId=src.id,dst.id;local genome=S.encode(src.contents[1].cell.genome);assert(T.collect(s,src.id));assert(V.count(src)==0 and s.desktop.pipette.sample.quantity==1);assert(T.dispense(s,dst.id));assert(V.count(dst)==1 and src.id==sourceId and dst.id==destId and S.encode(dst.contents[1].cell.genome)==genome and not s.desktop.pipette.sample and dst.cultivating) end)
 test('No unlimited cells from repeated collection or arbitrary loose-cell quantity',function() local s=seeded();local src=s.vessels[5];assert(T.collect(s,src.id));assert(not T.collect(s,src.id));assert(T.dispense(s,s.vessels[1].id));assert(not T.collect(s,src.id));local before=#s.cells;assert(not V.transfer(s,1,2,5));assert(#s.cells==before and V.count(s.vessels[2])==0) end)
 test('Empty, closed and frozen sources reject sample collection',function() local s=seeded();local v=s.vessels[5];v.closed=true;assert(not T.collect(s,v.id));v.closed=false;v.frozen=true;assert(not T.collect(s,v.id));v.frozen=false;assert(not T.collect(s,s.vessels[1].id));assert(V.count(v)==1 and not s.desktop.pipette.sample) end)
 test('Incompatible destination rejects transfer without losing loaded sample',function() local s=seeded();assert(T.seed(s,s.vessels[1].id,1));assert(T.collect(s,s.vessels[5].id));local before=S.encode(s.desktop.pipette.sample);assert(not T.dispense(s,s.vessels[1].id));assert(S.encode(s.desktop.pipette.sample)==before and V.count(s.vessels[1])==1) end)
 test('Full, closed, frozen and unsuitable targets reject without mutation',function() local s=seeded();assert(T.collect(s,s.vessels[5].id));local v=s.vessels[1];v.closed=true;assert(not T.dispense(s,v.id));v.closed=false;v.frozen=true;assert(not T.dispense(s,v.id));v.frozen=false;v.nutrients=0;assert(not T.dispense(s,v.id));assert(s.desktop.pipette.sample and V.count(v)==0);v.nutrients=1;v.contents={{cell=G.copy(s.desktop.pipette.sample.cell),count=8}};assert(not T.dispense(s,v.id) and V.count(v)==8) end)
 test('Cross-contamination follows reused dropper, sterilization removes residue',function() local s=seeded();local a,b,c=s.vessels[5],s.vessels[1],s.vessels[2];assert(T.collect(s,a.id));assert(T.dispense(s,b.id));assert(T.seed(s,c.id,1));assert(T.collect(s,c.id));assert(s.desktop.pipette.sample.contamination>=.15);assert(not T.clean(s));s.desktop.pipette.sample=nil;assert(T.clean(s) and s.desktop.pipette.clean and not s.desktop.pipette.residueGenome) end)
 test('Cultures progress while laboratory is hidden; frozen cultures suspend',function() local s=seeded();assert(T.collect(s,s.vessels[5].id));assert(T.dispense(s,s.vessels[1].id));M.setGroup(s,'laboratory',false);local v=s.vessels[1];B.update(s,50);assert(V.count(v)>1 and v.nutrients<1 and s.time>49);v.frozen=true;local before=S.encode(v);B.update(s,2);assert(S.encode(v)==before) end)
 test('Vessel temperature and contamination change biological growth',function() local a,b=seeded(),seeded();local va,vb=a.vessels[5],b.vessels[5];va.kind=1;vb.kind=1;va.cultivating=true;vb.cultivating=true;vb.temperature=60;V.update(a,30);V.update(b,30);assert(V.count(va)>V.count(vb) and vb.health<va.health) end)
 test('Genome Undo restores both alleles and provenance',function() local s=state();local source=s.cells[1];local original=S.encode(source.genome);assert(E.begin(source));local l=E.draft.chromosomes[1].loci[2];assert(E.change('a',l.a==3 and -1 or 1));assert(E.undo());assert(S.encode(E.draft)==original and S.encode(source.genome)==original) end)
 test('Forge dosage and regulation have real expression effects, support undo',function() local s=state();E.begin(s.cells[1]);E.site=1;E.selected=2;E.draft.chromosomes[2].loci[1].a=1;E.draft.chromosomes[2].loci[1].b=1;local before=G.value(E.draft,2);assert(E.operation('duplicate'));assert(G.value(E.draft,2)>before);assert(E.operation('delete'));assert(G.value(E.draft,2)==0);assert(E.undo());assert(G.value(E.draft,2)>0);assert(E.operation('restore'));assert(G.value(E.draft,2)==before);assert(E.operation('regulate'));assert(#E.draft.regulation==1 and G.valid(E.draft)) end)
 test('Forge splice, archive and exact installation retain canonical genome',function() local s=state();E.begin(s.cells[1]);E.site=3;E.selected=13;local donor={genome=s.cells[2].genome};assert(E.operation('splice',donor));assert(S.encode(E.draft.chromosomes[13].loci[3])==S.encode(donor.genome.chromosomes[13].loci[3]));assert(E.commit(s,B));local e=assert(B.queue(s,E.draft,'test',0));assert(S.encode(e.genome)==S.encode(E.draft));assert(S.encode(s.materials[1].genome.chromosomes)==S.encode(E.draft.chromosomes)) end)
 test('Genome editor callbacks still preview, archive and incubate viable edited organism',function() local s=state();local original=G.copy(require('audit_examples').compact.genome);E.begin({id=99,genome=original});E.site=1;E.selected=23;local old=E.draft.chromosomes[23].loci[1].a;E.change('a',old==3 and -1 or 1);local callbacks={};E.draw(s,{B=B,C={},source={id=99,genome=original},text=function() end,msg=function() end,button=function(name,x,y,w,h,fn) callbacks[name]=fn end});callbacks.Preview();assert(E.forecast.viable);callbacks['Save DNA copy']();callbacks['Incubate exact edited genome']();assert(#s.eggs==1);B.update(s,60);assert(#s.organisms==1 and s.organisms[1].alive and G.hash(s.organisms[1].genome)==G.hash(E.draft)) end)
 test('Habitat movement uses same organism identity, genome, anatomy and memories',function() local s=state();local o=assert(B.spawn(s,G.copy(require('audit_examples').compact.genome),'test',0));o.worldId='terrarium';o.cognition={memories={{kind='test',strength=.8}},relationships={},events={}};local a=o.anatomy;local g=G.hash(o.genome);assert(Worlds.move(s,o.id,'desktop',true));assert(o.worldId=='desktop' and o.anatomy==a and G.hash(o.genome)==g and #o.cognition.memories==1);assert(Worlds.move(s,o.id,'terrarium',true)) end)
 test('Aquariums keep distinct water chemistry and physiological exposure',function() local s=state();local fresh=Worlds.find(s,'freshwater');local salt=Worlds.find(s,'saltwater');local o=assert(B.spawn(s,G.copy(require('audit_examples').compact.genome),'test',0));o.worldId='saltwater';o.x=.5;o.y=.5;B.update(s,1);assert(o.environment=='saltwater' and o.age>0 and fresh.habitat.cells[1].salinity==0 and salt.habitat.cells[1].salinity==1 and fresh.habitat~=salt.habitat) end)
 test('Partitioned worlds do not duplicate age increments or organisms',function() local s=state();local o=assert(B.spawn(s,G.copy(require('audit_examples').compact.genome),'test',0));o.worldId='terrarium';local age=o.age;B.update(s,1);assert(math.abs(o.age-age-1)<1e-8 and #s.organisms==1 and math.abs(s.time-1)<1e-8) end)
 test('World queues retain embryos through development without ID duplication',function() local s=state();B.queue(s,G.copy(require('audit_examples').compact.genome),'test',0);B.update(s,60);assert(#s.eggs==0 and #s.organisms==1 and s.organisms[1].worldId=='terrarium');local ids={};for _,c in ipairs(s.cells) do assert(not ids[c.id]);ids[c.id]=true end;for _,o in ipairs(s.organisms) do assert(not ids[o.id]);ids[o.id]=true end end)
 test('Research records refer to the same organisms used by habitat simulation',function() local s=state();local o=assert(B.spawn(s,G.copy(require('audit_examples').compact.genome),'test',0));o.worldId='terrarium';B.update(s,1);local r=s.organisms[1];assert(r==o and r.stats.STR and r.cognition and r.vitals);local copy=assert(Store.decode(Store.payload(s,123),B));assert(copy.organisms[1].id==o.id and G.hash(copy.organisms[1].genome)==G.hash(o.genome)) end)
 test('Versioned envelope preserves layout, containers, loaded samples and editor draft',function() local s=seeded();local o=M.add(s,'dish',s.vessels[1].id,nil,-1600,100);M.remember(o,monitors);o.locked=true;assert(T.collect(s,s.vessels[5].id));E.begin(s.cells[1]);local r,why,stamp=Store.decode(Store.payload(s,123456),B);assert(r,why);assert(stamp==123456 and r.desktop.objects[1].locked and r.desktop.objects[1].x==-1600 and r.desktop.pipette.sample.quantity==1 and r.desktop.editor.draft and r.vessels[1].id==s.vessels[1].id) end)
 test('Version-4 manual saves migrate without discarding cells, embryos or old cultures',function() local old=B.new(34);B.collect(old);assert(B.cultivate(old,1,1));local r=assert(Store.decode('return '..S.encode(old),B));assert(#r.cells==6 and #r.dishes==1 and r.desktop.version==1 and #r.vessels==6) end)
 test('Invalid and future saves are rejected',function() assert(not Store.decode('return {desktopSchema=99}',B));assert(not Store.decode('return os.execute("bad")',B));assert(not Store.decode('broken!',B)) end)
 test('Procedural equipment has transparent exteriors and visible culture interiors',function() local s=seeded();local Art=require('desktop_art');require('rendering').init();local o=M.add(s,'dish',s.vessels[1].id);local canvas,data=Art.render(s,o,1);local _,_,_,corner=data:getPixel(0,0);local _,_,_,center=data:getPixel(118,112);assert(corner==0 and center>.1);for _,kind in ipairs({'vial','dropper','forge','workstation','rack','terrarium','freshwater','saltwater'}) do local entity=kind=='vial' and s.vessels[5].id or kind;local obj=M.add(s,kind,entity,kind=='terrarium' and 'habitats' or nil);local image=select(2,Art.render(s,obj,1));assert(image:getWidth()>20) end
  local atlas=love.graphics.newCanvas(1440,850);love.graphics.push('all');love.graphics.setCanvas({atlas,stencil=true});love.graphics.clear(.035,.055,.065,1);local x,y=25,25;for _,obj in ipairs(s.desktop.objects) do if x+obj.w>1430 then x=25;y=y+330 end;love.graphics.push();love.graphics.translate(x,y);Art.draw(s,obj);love.graphics.pop();x=x+obj.w+25 end;love.graphics.setCanvas();love.graphics.pop();local data=atlas:newImageData();local f=assert(io.open((love.filesystem.isFused() and love.filesystem.getSourceBaseDirectory() or love.filesystem.getSource())..'/desktop-art-preview.png','wb'));f:write(data:encode('png'):getString());f:close()
 end)
 require('desktop_app_tests')(B,test)
 if native then
  local N=require('native_windows');local Host=require('desktop_host');local s=seeded();local initialized=false
  test('Native tray and independent layered windows initialize',function() Host.monitors=N.init({test=true});initialized=true;Host.testing=true;Host.context={B=B,getState=function() return s end,msg=function() end,open=function() end};Host.sync();assert(N.control and N.tray and #s.desktop.objects>5);Host.render(true) end)
  if initialized then
   test('Native Petri dish moves using signed Windows screen coordinates',function() local o;for _,v in ipairs(s.desktop.objects) do if v.kind=='dish' then o=v;break end end;local m=Host.monitors[math.min(2,#Host.monitors)];o.x=m.x+30;o.y=m.y+30;M.remember(o,Host.monitors);Host.render(true);local r=N.bounds(Host.windows[o.id]);assert(r.x==o.x and r.y==o.y);lines[#lines+1]=#Host.monitors>1 and 'INFO Native move targeted actual second monitor.' or 'SKIP Physical second-monitor move: only one connected display. Synthetic mixed-DPI tests passed.' end)
   test('Native host routes counted dropper transfer to actual vessel records',function() local src=s.vessels[5];local target=s.vessels[1];local sourceObject,destObject;for _,o in ipairs(s.desktop.objects) do if o.entityId==src.id then sourceObject=o end;if o.entityId==target.id then destObject=o end end;s.desktop.tool='dropper';Host.event({type='objectMenu',id=sourceObject.id});assert(s.desktop.pipette.sample and V.count(src)==0);Host.click(destObject,118,112);Host.update(.5);assert(V.count(target)==1 and not s.desktop.pipette.sample);Host.render(true) end)
   test('Native hide and restore keeps all IDs, handles, locks, layouts and sample quantities',function() local objectCount=#s.desktop.objects;local before=S.encode(s.vessels);local positions=M.layout(s);local handles={};for id,w in pairs(Host.windows) do handles[id]=w.hwnd end;Host.toggle('laboratory');for _,o in ipairs(s.desktop.objects) do if o.group=='laboratory' then assert(not Host.windows[o.id].visible) else assert(Host.windows[o.id].visible) end end;Host.toggle('laboratory');assert(#s.desktop.objects==objectCount and S.encode(s.vessels)==before and S.encode(M.layout(s))==S.encode(positions));for id,w in pairs(Host.windows) do assert(w.hwnd==handles[id]) end end)
   test('Native message pump receives input for our own objects only',function() local o=s.desktop.objects[1];local win=Host.windows[o.id];N.testMessage(win,0x201,0,118+112*65536);N.testMessage(win,0x202,0,118+112*65536);local events=N.pump();local down,up=false,false;for _,e in ipairs(events) do if e.id==o.id and e.type=='down' then down=true end;if e.id==o.id and e.type=='up' then up=true end end;assert(down and up) end)
   test('Transparent Petri corners pass native hit testing while culture pixels receive input',function() local o;for _,obj in ipairs(s.desktop.objects) do if obj.kind=='dish' then o=obj;break end end;local monitor=M.monitorAt(Host.monitors,o.x,o.y);local factor=o.scale*monitor.dpi/96;local _,data=require('desktop_art').render(s,o,factor);local win=Host.windows[o.id];N.present(win,data,o.x,o.y,true,999);assert(N.isVisible(win));assert(N.windowAt(o.x+2,o.y+2)~=win.hwnd,'Transparent corner intercepts input');assert(N.windowAt(o.x+math.floor(118*factor),o.y+math.floor(112*factor))==win.hwnd,'Visible culture fails hit test') end)
   test('Left-button drag and right-click aspiration work with actual native events',function() local dropper,source;for _,o in ipairs(s.desktop.objects) do if o.kind=='dropper' then dropper=o end;if o.kind=='dish' and o.entityId==s.vessels[1].id then source=o end end;s.desktop.pipette.sample=nil;local mon=M.monitorAt(Host.monitors,source.x,source.y);dropper.scale=source.scale;local factor=dropper.scale*mon.dpi/96;dropper.x=source.x+(118-44)*factor;dropper.y=source.y+(112-214)*factor;local win=Host.windows[dropper.id];Host.render();N.testMessage(win,0x201,0,44+120*65536);for _,e in ipairs(N.pump()) do Host.event(e) end;assert(dropper.drag and s.desktop.tool=='dropper');N.testMessage(win,0x205,0,44+120*65536);for _,e in ipairs(N.pump()) do Host.event(e) end;assert(s.desktop.pipette.sample and V.count(s.vessels[1])==0);N.testMessage(win,0x202,0,44+120*65536);for _,e in ipairs(N.pump()) do Host.event(e) end;assert(not dropper.drag);assert(T.dispense(s,s.vessels[1].id)) end)
   test('Atomic desktop save and restart decode preserve real state',function() assert(Store.save(s,'desktop-acceptance-test.lua',os.time()));local raw=assert(love.filesystem.read('desktop-acceptance-test.lua'));local restored=assert(Store.decode(raw,B));assert(restored.vessels[1].id==s.vessels[1].id and V.count(restored.vessels[1])==1);assert(#restored.desktop.objects==#s.desktop.objects);love.filesystem.remove('desktop-acceptance-test.lua');love.filesystem.remove('desktop-acceptance-test.lua.backup') end)
   test('Native cleanup removes every equipment HWND and tray icon',function() local handles={};for _,win in pairs(Host.windows) do handles[#handles+1]=win end;N.shutdown();assert(next(N.windows)==nil and not N.tray and not N.control);Host.context=nil;Host.windows={} end)
  end
 end
 local summary=table.concat(lines,'\n')..'\n'..#lines..' result lines; '..failed..' failures.\n';if failed>0 then error(summary,0) end;return summary
end
